import {C,trashTypes as T,facilityTypes as F,oniTypes,traits,upgrades,waveDefinitions as W,weatherEffects} from './config.js';
export function pathfind(a,b,facilities,rows=14){const start={x:Math.round(a.x),y:Math.round(a.y)},goal={x:Math.round(b.x),y:Math.round(b.y)},key=p=>p.y*24+p.x,blocked=new Set();for(const f of facilities)for(let y=f.y;y<f.y+2;y++)for(let x=f.x;x<f.x+2;x++)blocked.add(y*24+x);if(blocked.has(key(goal)))return null;const q=[start],prev=new Map([[key(start),null]]);for(let i=0;i<q.length;i++){let p=q[i];if(key(p)===key(goal)){let out=[];while(prev.get(key(p))!==null){out.push(p);p=prev.get(key(p))}return out.reverse()}for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){let n={x:p.x+dx,y:p.y+dy},k=key(n);if(n.x<0||n.x>=24||n.y<4||n.y>=rows||blocked.has(k)||prev.has(k))continue;prev.set(k,p);q.push(n)}}return null}
export class Game{
 constructor(random=Math.random){this.random=random;this.reset()}
 reset(){Object.assign(this,{state:'title',wave:0,time:0,totalTime:0,money:C.startMoney,profit:0,heat:0,flow:0,maxFlow:0,lastSale:-99,rescued:0,burned:0,total:0,facilities:[],onis:[],trucks:[],effects:[],buffs:{},selected:null,land:11,nextId:1,choices:[],taken:false,shout:0,shoutUsed:false,weather:'normal',events:[],returned:0});this.addFacility('wash',3,6);this.addFacility('press',7,6);this.addOni('wash',1);this.addOni('press',2);this.addOni('wash',1)}
 event(kind,text,x=12,y=5){this.events.push({kind,text});if(this.events.length>20)this.events.shift();this.effects.push({text,x,y,life:2});if(this.effects.length>20)this.effects.shift()}
 addFacility(type,x,y){let f={id:this.nextId++,type,x,y,level:1,input:[],output:[],jobs:[]};this.facilities.push(f);return f}
 addOni(type=oniTypes[Math.floor(this.random()*5)],facility=this.facilities[0].id){let trait=Object.keys(traits)[Math.floor(this.random()*4)],f=this.facilities.find(f=>f.id===facility);let o={id:this.nextId++,type,trait,facility,x:f.x,y:f.y-1,stamina:trait==='tough'?120:100,max:trait==='tough'?120:100,task:null,path:[],carry:null,rest:false};this.onis.push(o);return o}
 entry(f){return{x:f.x,y:f.y-1}}
 canPlace(type,x,y,ignore=null){if(x<1||x>21||y<6||y+1>=this.land)return false;const fs=this.facilities.filter(f=>f.id!==ignore);if(fs.some(f=>x<f.x+2&&x+2>f.x&&y<f.y+2&&y+2>f.y))return false;const next=[...fs,{id:ignore,type,x,y}];return next.every(f=>pathfind({x:0,y:4},this.entry(f),next,this.land)!==null)}
 build(type,x,y){if(this.state!=='prep'||this.facilities.length>=C.maxFacilities||this.money<F[type].price||!this.canPlace(type,x,y))return false;this.money-=F[type].price;this.addFacility(type,x,y);return true}
 move(id,x,y){const f=this.facilities.find(f=>f.id===id);if(this.state!=='prep'||!f||!this.canPlace(f.type,x,y,id))return false;f.x=x;f.y=y;for(const o of this.onis){if(o.task&&!o.carry)o.task.item.owner=null;o.task=null;o.path=[];let home=this.facilities.find(f=>f.id===o.facility);Object.assign(o,this.entry(home))}return true}
 assign(id,fid){if(this.state!=='prep')return false;let o=this.onis.find(o=>o.id===id),f=this.facilities.find(f=>f.id===fid);if(!o||!f)return false;if(o.task&&!o.carry)o.task.item.owner=null;if(o.carry){const old=this.facilities.find(f=>f.id===o.facility);old.input.push({item:o.carry,oni:o.id});o.carry=null}o.facility=fid;o.task=null;o.path=[];Object.assign(o,this.entry(f));return true}
 recruit(){if(this.state!=='prep'||this.money<C.oniPrice||this.onis.length>=C.maxOni)return false;this.money-=C.oniPrice;this.addOni();return true}
 level(id){let f=this.facilities.find(f=>f.id===id),cost=C.levelPrice*f.level;if(this.state!=='prep'||this.money<cost||f.level>=4)return false;this.money-=cost;f.level++;return true}
 expand(){if(this.state!=='prep'||this.land===14||this.money<C.landPrice)return false;this.money-=C.landPrice;this.land=14;return true}
 prepare(){this.state='prep';this.taken=true}
 choose(id){if(this.state!=='upgrade'||this.taken||!this.choices.some(u=>u.id===id))return false;this.buffs[id]=(this.buffs[id]||0)+1;this.taken=true;this.state='prep';return true}
 startWave(){if(this.state!=='prep')return false;this.wave++;this.state='wave';this.time=0;this.nextSpawn=0;this.waveStart={profit:this.profit,rescued:this.rescued,total:this.total};this.shoutUsed=false;this.shout=0;this.weather=this.random()<this.heat/130?['hot','rain','storm'][Math.floor(this.random()*3)]:'normal';for(const o of this.onis){if(this.buffs.water)o.stamina=o.max}this.event('wave',`Wave ${this.wave} / ${W[this.wave-1].name}`);return true}
 command(){if(this.state!=='wave'||this.shoutUsed)return false;this.shoutUsed=true;this.shout=C.shoutSeconds;this.event('shout','まだ使える！');return true}
 heatEffect(o){const resist=o.trait==='cool'?.6:1;return{recovery:1-(this.heat>=25?.13:0)*resist*Math.pow(.5,this.buffs.shade||0),drain:1+(this.heat>=75?.5:this.heat>=50?.25:0)*resist}}
 speed(o){return C.move*(1+.1*(this.buffs.speed||0))*(o.trait==='fast'?1.15:1)*(o.stamina<25?.72:1)*(this.shout>0?1.55:1)*(o.carry&&['can','battery'].includes(o.carry.type)?1+.25*(this.buffs.magnet||0):1)}
 synergy(f){return this.facilities.some(g=>g!==f&&[['wash','press'],['break','repair']].some(p=>p.includes(f.type)&&p.includes(g.type)&&f.type!==g.type)&&Math.abs(f.x-g.x)+Math.abs(f.y-g.y)<=5)?1.1:1}
 rate(f,o){return(1+.3*(f.level-1))*(o?.type===f.type?1.25:1)*(o&&o.stamina<25?.8:1)*(this.shout>0?1.5:1)*this.synergy(f)*(f.type==='wash'?1+.25*(this.buffs.wash||0):1)}
 capacity(f){return F[f.type].buffer+(this.buffs.buffer||0)}
 activeItems(){return this.trucks.reduce((n,t)=>n+t.items.length,0)+this.facilities.reduce((n,f)=>n+f.input.length+f.output.length+f.jobs.length,0)+this.onis.filter(o=>o.carry).length}
 spawn(){if(this.trucks.length>=C.maxTrucks)return;let w=W[this.wave-1],room=C.maxItems-this.activeItems(),items=[];for(let i=0;i<Math.min(room,w.load+weatherEffects[this.weather].extra);i++){let type=w.mix[Math.floor(this.random()*w.mix.length)];let route=[...T[type].route];if(type==='phone'&&!this.facilities.some(f=>f.type==='repair')&&this.facilities.some(f=>f.type==='break'))route=['break'];items.push({id:this.nextId++,type,route,step:0,owner:null})}if(items.length){this.total+=items.length;this.trucks.push({id:this.nextId++,x:-1,items})}}
 burn(items){for(const item of items){this.burned++;this.heat=Math.min(100,this.heat+T[item.type].heat*C.heatScale*Math.pow(.85,this.buffs.eco||0))}if(items.length)this.event('burn',`${items.length}個 焼却`,22,3)}
 sale(item,f,o){this.flow=this.totalTime-this.lastSale<C.flowWindow?this.flow+1:1;this.lastSale=this.totalTime;this.maxFlow=Math.max(this.maxFlow,this.flow);const price=Math.round(T[item.type].profit*(item.type==='phone'&&f.type==='break'?.6:1)*(o?.trait==='careful'?1.1:1)*(f.type==='repair'?1+.25*(this.buffs.repair||0):1)*(1+Math.min(.1,this.flow*.005)));this.profit+=price;this.money+=price;this.event('sale',`+¥${price}`,f.x,f.y);if(this.flow%10===0)this.event('flow','……よし。');if(['cloth','phone'].includes(item.type)){this.returned++;if(this.returned%3===0)this.event('reuse',item.type==='phone'?'直る。街でもう一度。':'お気に入りを、もう一度。',16,1)}}
 findTask(o,f){if(f.input.length+f.jobs.length+this.onis.filter(a=>a.facility===f.id&&a.task).length>=this.capacity(f)+F[f.type].slots)return;let candidates=[];for(const g of this.facilities)for(const item of g.output)if(item.route[item.step]===f.type&&!item.owner)candidates.push({item,source:g,kind:'output',point:this.entry(g)});for(const t of this.trucks)if(t.x>=2&&t.x<=19)for(const item of t.items)if(item.route[item.step]===f.type&&!item.owner)candidates.push({item,source:t,kind:'truck',point:{x:Math.min(20,Math.ceil(t.x+1)),y:4}});candidates.sort((a,b)=>(Math.abs(o.x-a.point.x)+Math.abs(o.y-a.point.y))-(Math.abs(o.x-b.point.x)+Math.abs(o.y-b.point.y)));for(const task of candidates){let p=pathfind(o,task.point,this.facilities,this.land);if(p){task.item.owner=o.id;o.task=task;o.path=p;return}}}
 stepOni(o,dt){let f=this.facilities.find(f=>f.id===o.facility),h=this.heatEffect(o);if(o.stamina<8)o.rest=true;if(o.rest&&o.stamina>o.max*.65)o.rest=false;if(o.rest){o.stamina=Math.min(o.max,o.stamina+C.recovery*h.recovery*dt);return}if(!o.task&&!o.carry)this.findTask(o,f);if(o.task?.kind==='truck'&&!o.carry){const t=o.task.source;if(!this.trucks.includes(t)||!t.items.includes(o.task.item)||t.x>20){o.task.item.owner=null;o.task=null;o.path=[];return}let target={x:Math.min(21,Math.ceil(t.x+1)),y:4};if(!o.path.length||o.path.at(-1).x!==target.x)o.path=pathfind(o,target,this.facilities,this.land)||[]}
 if(o.path.length){let target=o.path[0],dx=target.x-o.x,dy=target.y-o.y,d=Math.hypot(dx,dy),step=this.speed(o)*dt;if(d<=step){o.x=target.x;o.y=target.y;o.path.shift()}else{o.x+=dx/d*step;o.y+=dy/d*step}o.stamina=Math.max(0,o.stamina-C.staminaDrain*h.drain*weatherEffects[this.weather].drain*dt)}else if(o.carry){f.input.push({item:o.carry,oni:o.id});o.carry=null;o.task=null}else if(o.task){let source=o.task.source,items=o.task.kind==='truck'?source.items:source.output,index=items.indexOf(o.task.item);if(index>=0){o.carry=items.splice(index,1)[0];if(o.task.kind==='truck'){this.rescued++;this.event('rescue','救出',o.x,o.y)}o.path=pathfind(o,this.entry(f),this.facilities,this.land)||[]}else{o.task=null}}else o.stamina=Math.min(o.max,o.stamina+C.recovery*h.recovery*dt)}
 tick(dt){if(this.state!=='wave')return;this.time+=dt;this.totalTime+=dt;this.shout=Math.max(0,this.shout-dt);if(this.totalTime-this.lastSale>C.flowWindow)this.flow=Math.max(0,this.flow-dt*2);for(const e of this.effects){e.life-=dt;e.y-=dt*.2}this.effects=this.effects.filter(e=>e.life>0);if(this.time<C.spawnUntil&&this.time>=this.nextSpawn){this.spawn();this.nextSpawn=this.time+W[this.wave-1].interval}for(const t of this.trucks)t.x+=C.truckSpeed*dt;for(const t of this.trucks.filter(t=>t.x>24)){this.burn(t.items);this.trucks.splice(this.trucks.indexOf(t),1)}if(this.heat>=100){this.finish(false);return}for(const o of this.onis)this.stepOni(o,dt);for(const f of this.facilities){while(f.input.length&&f.jobs.length<F[f.type].slots+Math.floor((f.level-1)/2)){let job=f.input.shift();job.progress=0;f.jobs.push(job)}for(const job of [...f.jobs]){let o=this.onis.find(o=>o.id===job.oni);job.progress+=dt*this.rate(f,o)/(F[f.type].seconds*(job.item.type==='card'?weatherEffects[this.weather].paper:1));if(o)o.stamina=Math.max(0,o.stamina-dt*.5*this.heatEffect(o).drain);if(job.progress>=1){let item=job.item;if(item.step+1<item.route.length&&f.output.length>=this.capacity(f))continue;f.jobs.splice(f.jobs.indexOf(job),1);item.step++;item.owner=null;if(item.step>=item.route.length)this.sale(item,f,o);else f.output.push(item)}}}if(this.time>=C.duration&&!this.trucks.length)this.endWave()}
 endWave(){const w=this.waveStart,avoid=(this.rescued-w.rescued)/Math.max(1,this.total-w.total);if(avoid>=.75)this.heat=Math.max(0,this.heat-4);this.summary={profit:this.profit-w.profit,avoid};this.state='upgrade';this.taken=false;this.choices=[...upgrades].sort(()=>this.random()-.5).slice(0,3);if(this.wave===8)this.finish(true)}
 finish(clear){this.state='result';this.clear=clear;const score=this.profit/100+this.rescued/Math.max(1,this.total)*55+(100-this.heat)*.3;this.rank=score>=105?'S':score>=75?'A':score>=45?'B':'C';if(!clear&&this.rank==='S')this.rank='A'}
}

